-- Permit Finance to close an approved deal only after operational and receivable gates are fully satisfied.
create or replace function public.deal_complete_v1(p_deal_id uuid,p_reason text default null) returns public.deals language plpgsql security definer set search_path=public as $$declare d public.deals;role text:=public.deal_current_role();begin if role not in ('admin','ceo','manager','finance') then raise exception 'Deal completion requires manager or finance permission.';end if;select * into d from public.deals where id=p_deal_id for update;if not found then raise exception 'Deal not found.';end if;if d.status<>'approved' then raise exception 'Only approved deals can be completed.';end if;if not exists(select 1 from public.shipments where deal_id=p_deal_id) then raise exception 'At least one shipment is required before deal completion.';end if;if exists(select 1 from public.shipments where deal_id=p_deal_id and status::text not in ('delivered','cancelled')) then raise exception 'All linked shipments must be delivered or cancelled before completing the deal.';end if;if exists(select 1 from public.invoices where deal_id=p_deal_id and invoice_type='receivable' and status not in ('paid','cancelled')) then raise exception 'All linked receivable invoices must be paid or cancelled before completing the deal.';end if;update public.deals set status='completed',updated_at=now() where id=p_deal_id returning * into d;insert into public.deal_events(deal_id,event_type,from_value,to_value,reason,performed_by) values(p_deal_id,'completed','approved','completed',nullif(trim(coalesce(p_reason,'')),''),auth.uid());return d;end$$;
revoke all on function public.deal_complete_v1(uuid,text) from public,anon;grant execute on function public.deal_complete_v1(uuid,text) to authenticated,service_role;
